#include <vector>
#include <omp.h>

bool reduceLogicalXOR(std::vector<bool> const& x) {
    int xor_accum = 0;  // use int for OpenMP reduction compatibility

    #pragma omp parallel for reduction(^:xor_accum)
    for (std::size_t i = 0; i < x.size(); ++i) {
        xor_accum ^= static_cast<int>(x[i]);
    }

    return xor_accum != 0;
}
